1209	+          Board
1210	+        </button>
1211	+        <span className="h-4 w-px bg-border" aria-hidden="true" />
1212	+
1213	+        <div className="flex min-w-0 flex-1 flex-wrap items-center gap-2">
1214	+          {/* Copy feature id button */}
1215	+          <button
